(args, got) => {
      const s = args[0];
      if (typeof got !== "string") return false;
      // 1. balanced
      let depth = 0;
      for (const c of got) {
        if (c === "(") depth++;
        else if (c === ")" && --depth < 0) return false;
      }
      if (depth !== 0) return false;
      // 2. a subsequence of s
      let j = 0;
      for (let i = 0; i < s.length && j < got.length; i++) if (s[i] === got[j]) j++;
      if (j !== got.length) return false;
      // 3. as long as possible: greedy matching finds the brackets that must go
      let open = 0, stray = 0;
      for (const c of s) {
        if (c === "(") open++;
        else if (c === ")") { if (open > 0) open--; else stray++; }
      }
      return got.length === s.length - stray - open;
    }

