function trimToBalanced(s: string): string {
  const chars = s.split("");
  const open: number[] = []; // indices of ( not matched yet
  for (let i = 0; i < chars.length; i++) {
    if (chars[i] === "(") open.push(i);
    else if (chars[i] === ")") {
      if (open.length) open.pop();
      else chars[i] = ""; // nothing to close
    }
  }
  for (const i of open) chars[i] = ""; // never closed
  return chars.join("");
}

