class Solution:
    def trimToBalanced(self, s: str) -> str:
        chars = list(s)
        open_idx = []  # indices of ( not matched yet
        for i, c in enumerate(chars):
            if c == "(":
                open_idx.append(i)
            elif c == ")":
                if open_idx:
                    open_idx.pop()
                else:
                    chars[i] = ""  # nothing to close
        for i in open_idx:
            chars[i] = ""  # never closed
        return "".join(chars)

