function trimToBalanced(s: string): string {
  const first: string[] = [];
  let depth = 0;
  for (const c of s) {
    if (c === ")") {
      if (depth === 0) continue;
      depth--;
    } else if (c === "(") depth++;
    first.push(c);
  }
  const out: string[] = [];
  depth = 0;
  for (let i = first.length - 1; i >= 0; i--) {
    const c = first[i];
    if (c === "(") {
      if (depth === 0) continue;
      depth--;
    } else if (c === ")") depth++;
    out.push(c);
  }
  return out.reverse().join("");
}

