class Solution:
    def trimToBalanced(self, s: str) -> str:
        first, depth = [], 0
        for c in s:
            if c == ")":
                if depth == 0:
                    continue
                depth -= 1
            elif c == "(":
                depth += 1
            first.append(c)
        out, depth = [], 0
        for c in reversed(first):
            if c == "(":
                if depth == 0:
                    continue
                depth -= 1
            elif c == ")":
                depth += 1
            out.append(c)
        return "".join(reversed(out))

